#!/usr/bin/env bash
#
# Post-pass for tools/vendor/expo-gl.sh: prove the rewrite actually happened.
#
#   tools/vendor/verify.sh [<dir>]
#
# A rewrite that half-worked is worse than one that did not run, because it
# compiles. Four things are checked, each with a silent failure mode:
#
#   1. No `OpenGLES/` include survives. This is the expensive one. Upstream's
#      pch.h reaches for Apple's deprecated EAGL GLES under __APPLE__, which
#      builds cleanly and then fights ANGLE at link or run time. Architecture.md
#      9 says ANGLE is the GL; anything reaching past it fails here.
#   2. No `expo::` / `namespace expo` / `gl_cpp` survives in code.
#   3. No EX-prefixed identifier survives in code, except the ones the rules
#      table explicitly allows with a reason.
#   4. Every file carries its provenance header, so nothing in the tree can be
#      mistaken for one of ours to edit.
#
# Exits non-zero naming the file and the line.
#
# Scope, stated rather than assumed: checks 2 and 3 read *code*, so the
# generated provenance header and comment text are skipped. Naming the upstream
# symbol a file replaces is the point of those comments, and a comment does not
# compile or link. Check 1 is not scoped that way -- an `#include` is matched
# wherever it appears, and any mention of EAGL or OpenGLES outside a comment is
# a finding too.

set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
RULES="$HERE/expo-gl.rules"
DIR="${1:-$ROOT/runtime/third_party/gl}"

say() { printf '%s\n' "$*" >&2; }

[ -f "$RULES" ] || { say "verify.sh: the rules table is missing: $RULES"; exit 1; }
if [ ! -d "$DIR" ]; then
  say "verify.sh: nothing to verify -- $DIR does not exist."
  say "  Run: tools/vendor/expo-gl.sh"
  exit 1
fi

command -v perl >/dev/null 2>&1 || { say "verify.sh: \`perl\` is not on PATH."; exit 1; }

# One perl pass, so a finding reports file, line and offending token together.
# `allow` rows come from the same table as the rewrite rules, so a token is only
# ever excused in one place and with its reason beside it.
RULES_PATH="$RULES" SCAN_DIR="$DIR" perl -e '
use strict;
use warnings;
use File::Find;

my $rules = $ENV{RULES_PATH};
my $dir   = $ENV{SCAN_DIR};

open(my $rh, "<", $rules) or die "verify.sh: cannot read $rules: $!\n";
my @allow;
while (my $line = <$rh>) {
  next if $line =~ /^\s*(#|$)/;
  chomp $line;
  my @f = split(/\s*\|\s*/, $line, 4);
  next unless @f >= 3;
  for (@f) { s/^\s+//; s/\s+$//; }
  next unless $f[0] eq "allow";
  my $re = eval { qr/$f[1]/ };
  die "verify.sh: bad allow regex: $f[1]\n  $@" if $@;
  push @allow, $re;
}
close $rh;

my @files;
find(sub { push @files, $File::Find::name if -f $_ && $_ ne ".manifest" }, $dir);
@files = sort @files;
die "verify.sh: $dir holds no files.\n" unless @files;

my @findings;
my ($scanned, $sources) = (0, 0);

# Strip what is not code: a line comment to end of line, a /* */ that opens and
# closes on one line, and everything inside an open block comment. String
# literals are left alone -- "GL_EXT_texture_filter_anisotropic" is read back
# from the driver and is meant to survive, which is why it is an `allow` row.
sub code_of {
  my ($line, $in_block) = @_;
  my $out = "";
  my $i = 0;
  while ($i < length $line) {
    if ($$in_block) {
      my $end = index($line, "*/", $i);
      if ($end < 0) { return ($out, 1); }
      $$in_block = 0;
      $i = $end + 2;
      next;
    }
    my $lc = index($line, "//", $i);
    my $bc = index($line, "/*", $i);
    if ($lc >= 0 && ($bc < 0 || $lc < $bc)) {
      $out .= substr($line, $i, $lc - $i);
      return ($out, 0);
    }
    if ($bc >= 0) {
      $out .= substr($line, $i, $bc - $i);
      $$in_block = 1;
      $i = $bc + 2;
      next;
    }
    $out .= substr($line, $i);
    last;
  }
  return ($out, 0);
}

for my $path (@files) {
  my $rel = $path;
  $rel =~ s/^\Q$dir\E\/?//;

  open(my $fh, "<", $path) or die "verify.sh: cannot read $path: $!\n";
  my @lines = <$fh>;
  close $fh;
  $scanned++;

  # --- 4. provenance -------------------------------------------------------
  my $head = join("", @lines[0 .. ($#lines < 9 ? $#lines : 9)]);
  unless ($head =~ /GENERATED by tools\/vendor\/expo-gl\.sh/) {
    push @findings, "$rel:1: no provenance header -- this file did not come from expo-gl.sh"
      unless $rel eq "LICENSE-expo";
    next if $rel eq "LICENSE-expo";   # upstream text, carried across untouched
  }

  # VENDOR.md is the record of what was renamed, so it names the old names on
  # purpose. It is checked for its generated marker, above, and no further.
  next if $rel eq "VENDOR.md";
  $sources++;

  # Start after the generated header rather than at line 1: the header names the
  # upstream file it came from, which is provenance, not an unrewritten symbol.
  my $start = 0;
  for my $n (0 .. $#lines) {
    if ($lines[$n] =~ /See VENDOR\.md\./) { $start = $n + 1; last; }
  }

  my $in_block = 0;
  for my $n (0 .. $#lines) {
    my $line = $lines[$n];
    my $where = "$rel:" . ($n + 1);
    my ($code) = code_of($line, \$in_block);

    # --- 1. the EAGL trap ----------------------------------------------------
    # Scanned from line 0, unlike the rules below. $start exists so the
    # provenance header naming its upstream file is not read as an unrewritten
    # EX symbol -- but that header holds no GL include, and skipping past it
    # here left a blind spot: anything inserted ABOVE the header went unseen by
    # the one check whose silent failure costs the most.
    if ($line =~ /^\s*#\s*include\s*[<"](OpenGLES\/[^>"]*)[>"]/) {
      push @findings,
        "$where: Apple GLES include survived: <$1> -- ANGLE is the GL (Architecture.md 9)";
    }
    if ($code =~ /(OpenGLES\/[A-Za-z0-9_\/.]*)/) {
      push @findings, "$where: reaches Apple GLES directly: $1";
    }
    if ($code =~ /\b(EAGL[A-Za-z]*)/) {
      push @findings, "$where: EAGL is Apple context management: $1 -- ours is EGL, via GlSurface";
    }

    # The remaining rules start after the generated header.
    next if $n < $start;

    # --- 2. namespace --------------------------------------------------------
    if ($code =~ /(expo\s*::|namespace\s+expo\b|\bgl_cpp\b)/) {
      push @findings, "$where: unrewritten namespace: $1";
    }

    # --- 3. the EX prefix ----------------------------------------------------
    my $rest = $code;
    for my $re (@allow) { $rest =~ s/$re//g; }
    while ($rest =~ /\b(U?EX[A-Za-z0-9_]*)/g) {
      push @findings, "$where: unrewritten symbol: $1";
    }
  }
}

if (@findings) {
  print STDERR "verify.sh: the vendored tree is not fully rewritten ("
             . scalar(@findings) . " findings)\n";
  print STDERR "    $_\n" for @findings;
  print STDERR "\n  Each of these is a missing or mis-ordered row in tools/vendor/expo-gl.rules.\n";
  print STDERR "  Fix the table and re-run tools/vendor/expo-gl.sh -- never the output tree.\n";
  exit 1;
}

print STDERR ">>> verify.sh: $scanned files, $sources scanned as code"
           . " -- no OpenGLES/, no expo::, no EX symbol\n";
'
